// Generated by tools/ue-api/make_manifest.py from the Python the tools generate. Do not edit.
// The Unreal Python API each tool calls, so check_ue_compat can test a running editor for it.

export interface ApiManifest {
	/** Engine version the manifest was checked against */
	version: string;
	/** Per tool: [class, member] pairs that must exist, e.g. ["EditorAssetLibrary", "load_asset"] */
	tools: Record<string, [string, string][]>;
	/** Per tool: names that must exist directly on the unreal module */
	symbols: Record<string, string[]>;
	/** Per tool: Class.member entries the tool only uses after checking the engine has them */
	gated: Record<string, string[]>;
}

